"use client";
import {useEffect,useMemo,useState} from "react";
import {ACTION_TYPES,DEFAULT_PIPELINE,getClientCategories,getClientPipeline,getClientPipelineConfig,nowIso,today,uid} from "@/lib/state";
import {metrics,euro,metricsRange} from "@/lib/stats";

const api=async(url,opt={})=>{const r=await fetch(url,{headers:{"Content-Type":"application/json"},...opt});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||"Une erreur est survenue");return j};
const fmtDate=v=>v?new Date(v).toLocaleDateString("fr-FR",{weekday:"short",day:"2-digit",month:"short",year:"numeric"}):"—";
const fmtDateTime=v=>v?new Date(v).toLocaleString("fr-FR",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"}):"—";
const monthKey=v=>(v||"").slice(0,7);
const telHref=n=>n?`tel:${n}`:'#';
const waHref=n=>n?`https://wa.me/${String(n).replace(/\D/g,'')}`:'#';
const smsHref=n=>n?`sms:${n}`:'#';
const statusClass=s=>`status-pill status-${String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-')}`;
const hexToRgba=(hex,a=.12)=>{const h=String(hex||'#67707E').replace('#','');const v=h.length===3?h.split('').map(x=>x+x).join(''):h;const n=parseInt(v,16);return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`};
const rangeLabel=(start,end,mode)=>mode==='all'?'Toutes les données':`${new Date(start+'T12:00:00').toLocaleDateString('fr-FR')} → ${new Date(end+'T12:00:00').toLocaleDateString('fr-FR')}`;
function StatusPill({status,config=[]}){const st=config.find(x=>(x.label||x)===status);const color=st?.color||'#67707E';return <span className={statusClass(status)} style={{background:hexToRgba(color,.12),color}}>{status}</span>}
function Logo(){return <img className="presty-logo" src="/presty-logo.png" alt="Presty"/>}
function Field({label,type="text",value,onChange,placeholder,disabled=false}){return <label className="field"><span>{label}</span><input disabled={disabled} type={type} value={value??""} onChange={e=>onChange?.(e.target.value)} placeholder={placeholder}/></label>}
function SelectField({label,value,onChange,children,disabled=false}){return <label className="field"><span>{label}</span><select disabled={disabled} value={value??""} onChange={e=>onChange?.(e.target.value)}>{children}</select></label>}

function Auth({done}){const[init,setInit]=useState(null),[mode,setMode]=useState("login"),[f,setF]=useState({name:"",email:"",password:""}),[err,setErr]=useState(""),[message,setMessage]=useState(""),[loading,setLoading]=useState(false),[cooldown,setCooldown]=useState(0);useEffect(()=>{api("/api/setup").then(x=>{setInit(x.initialized);if(x.initialized===false)setMode("setup")}).catch(e=>setErr(e.message))},[]);useEffect(()=>{if(!cooldown)return;const t=setInterval(()=>setCooldown(x=>Math.max(0,x-1)),1000);return()=>clearInterval(t)},[cooldown]);async function submit(){try{setLoading(true);setErr("");setMessage("");if(mode==="forgot"){const r=await api("/api/auth/forgot-password",{method:"POST",body:JSON.stringify({email:f.email})});setMessage(r.message);setCooldown(60);return}await api(mode==="setup"?"/api/setup":"/api/auth/login",{method:"POST",body:JSON.stringify(f)});done()}catch(e){const m=e.message||"";if(m.includes('request this after')||m.includes('rate')){const sec=Number(m.match(/(\d+) seconds/)?.[1]||60);setCooldown(sec);setErr(`Une demande a déjà été envoyée. Réessayez dans ${sec} secondes.`)}else setErr(m)}finally{setLoading(false)}}return <div className="auth-page"><div className="auth-brand-panel"><Logo/><div className="auth-brand-copy"><span className="eyebrow light-text">PORTAIL CLIENT PRESTY</span><h1>Votre activité.<br/>Plus lisible.</h1><p>Contacts, suivi commercial, rendez-vous et performance dans un espace simple à utiliser au quotidien.</p></div></div><div className="auth-form-panel"><div className="auth-form-wrap"><span className="eyebrow">ESPACE SÉCURISÉ</span><h2>{mode==="setup"?"Créer le compte administrateur":mode==="forgot"?"Mot de passe oublié":"Connexion"}</h2><p className="auth-intro">{mode==="forgot"?"Indiquez votre email pour recevoir un lien sécurisé.":"Accédez à votre espace Presty."}</p>{mode==="setup"&&<Field label="Nom" value={f.name} onChange={v=>setF({...f,name:v})}/>}<Field label="Adresse email" type="email" value={f.email} onChange={v=>setF({...f,email:v})}/>{mode!=="forgot"&&<Field label="Mot de passe" type="password" value={f.password} onChange={v=>setF({...f,password:v})}/>} {err&&<div className="alert error">{err}</div>}{message&&<div className="alert success">{message}</div>}<button className="primary full" onClick={submit} disabled={loading||cooldown>0}>{loading?"Chargement…":cooldown?`Renvoyer dans ${cooldown}s`:mode==="setup"?"Créer mon compte admin":mode==="forgot"?"Envoyer le lien":"Se connecter"}</button>{init!==false&&<div className="auth-links">{mode==="forgot"?<button onClick={()=>setMode("login")}>← Retour à la connexion</button>:<button onClick={()=>setMode("forgot")}>Mot de passe oublié ?</button>}</div>}</div></div></div>}

export default function PrestyApp(){const[user,setUser]=useState(undefined),[state,setState]=useState(null),[tab,setTab]=useState("clients"),[selected,setSelected]=useState(""),[switchOpen,setSwitchOpen]=useState(false),[mobileNavOpen,setMobileNavOpen]=useState(false);async function refresh(){const s=await api("/api/auth/session");setUser(s.user);if(s.user){const d=await api("/api/state");setState(d.state);const ids=s.user.accessIds||[];if(s.user.role==="client")setSelected(s.user.institutId||ids[0]||"");else if(s.user.role==="setter"&&!selected)setSelected(ids[0]||"")}}useEffect(()=>{refresh()},[]);if(user===undefined)return <div className="loading"><img src="/presty-mark.png" alt=""/></div>;if(!user)return <Auth done={refresh}/>;if(!state)return <div className="loading">Chargement des données…</div>;
 const admin=user.role==="agency_admin",setter=user.role==="setter",client=user.role==="client";const iid=client?user.institutId:selected;const inClientWorkspace=Boolean(iid);const company=state.instituts.find(i=>i.id===iid);const allowedCompanies=admin?state.instituts:state.instituts.filter(i=>(user.accessIds||[]).includes(i.id));async function save(next){setState(next);await api("/api/state",{method:"PUT",body:JSON.stringify({state:next})})}
 const clientNav=[['dashboard','Tableau de bord'],['contacts','Contacts'],['crm','CRM'],['appointments','Rendez-vous'],['ads','Publicité'],['stats','Statistiques'],['settings','Paramètres']];const setterNav=[['dashboard','Tableau de bord'],['contacts','Contacts'],['crm','CRM'],['appointments','Rendez-vous']];const adminNav=[['clients','Comptes clients'],['users','Utilisateurs'],['settings','Paramètres']];const nav=admin&&!inClientWorkspace?adminNav:setter?setterNav:clientNav;
 function switchCompany(id){setSelected(id);setSwitchOpen(false);setTab('dashboard')}function backAdmin(){setSelected('');setSwitchOpen(false);setTab('clients')}
 return <div className="app-shell"><aside className={`sidebar ${mobileNavOpen?'mobile-open':''}`}><div className="sidebar-logo"><Logo/>{company&&<div className="workspace-name"><span>ESPACE CLIENT</span><strong>{company.companyName||company.name}</strong></div>}</div><nav>{nav.map(([id,label])=><button className={tab===id?'active':''} key={id} onClick={()=>{setTab(id);setMobileNavOpen(false)}}><span className="nav-dot"/>{label}</button>)}</nav><div className="sidebar-bottom"><button className="logout-btn" onClick={async()=>{await api('/api/auth/logout',{method:'POST'});location.reload()}}>↪ Déconnexion</button><div className="sync"><span className="status-dot"/>Données synchronisées</div></div></aside>{mobileNavOpen&&<button className="mobile-nav-backdrop" aria-label="Fermer le menu" onClick={()=>setMobileNavOpen(false)}/>}<div className="app-main"><header className="topbar"><div className="topbar-title"><button className="mobile-menu-button" aria-label="Ouvrir le menu" onClick={()=>setMobileNavOpen(true)}>☰</button><div><span className="eyebrow">{admin&&!inClientWorkspace?'ADMINISTRATION PRESTY':setter?'ESPACE SETTER':'ESPACE CLIENT'}</span><h2>{company?.companyName||company?.name||nav.find(x=>x[0]===tab)?.[1]}</h2></div></div><div className="top-actions">{admin&&inClientWorkspace&&<span className="admin-mode">Mode admin</span>}<div className="switch-wrap"><button className="profile-pill" onClick={()=>setSwitchOpen(v=>!v)}><span>{(user.name||user.email||'P')[0].toUpperCase()}</span><b>{user.name||'Compte'}</b><i>⌄</i></button>{switchOpen&&<div className="account-switcher">{admin&&<button onClick={backAdmin} className={!iid?'current':''}><strong>Administration Presty</strong><small>Vue globale</small></button>}{(admin||setter)&&<><div className="switch-title">Changer d’espace client</div>{allowedCompanies.map(c=><button key={c.id} className={iid===c.id?'current':''} onClick={()=>switchCompany(c.id)}><span className="switch-avatar">{c.name[0]}</span><div><strong>{c.companyName||c.name}</strong><small>{c.ville||'Compte client'}</small></div></button>)}</>}</div>}</div></div></header><main className="content">
 {tab==='dashboard'&&<Dashboard state={state} iid={iid}/>} {tab==='clients'&&admin&&!inClientWorkspace&&<Clients state={state} refresh={refresh} save={save} switchCompany={switchCompany}/>} {tab==='users'&&admin&&!inClientWorkspace&&<UsersAdmin state={state} refresh={refresh}/>} {tab==='contacts'&&inClientWorkspace&&<Contacts state={state} iid={iid} save={save}/>} {tab==='crm'&&<CRM state={state} iid={iid} admin={admin&&!inClientWorkspace} save={save}/>} {tab==='appointments'&&inClientWorkspace&&<Appointments state={state} iid={iid} save={save}/>} {tab==='ads'&&<Ads state={state} iid={iid}/>} {tab==='stats'&&inClientWorkspace&&<Stats state={state} iid={iid}/>} {tab==='settings'&&<Settings state={state} iid={iid} admin={admin&&!inClientWorkspace} user={user} save={save}/>} </main></div></div>}

function Dashboard({state,iid}){const[mode,setMode]=useState('month'),[customStart,setCustomStart]=useState(today()),[customEnd,setCustomEnd]=useState(today());const now=new Date();const ymd=d=>d.toISOString().slice(0,10);let start='',end='';if(mode==='today'){start=end=today()}else if(mode==='yesterday'){const d=new Date(now);d.setDate(d.getDate()-1);start=end=ymd(d)}else if(mode==='7d'){const d=new Date(now);d.setDate(d.getDate()-6);start=ymd(d);end=today()}else if(mode==='30d'){const d=new Date(now);d.setDate(d.getDate()-29);start=ymd(d);end=today()}else if(mode==='month'){start=`${today().slice(0,7)}-01`;end=today()}else if(mode==='lastMonth'){const d=new Date(now.getFullYear(),now.getMonth()-1,1),e=new Date(now.getFullYear(),now.getMonth(),0);start=ymd(d);end=ymd(e)}else if(mode==='custom'){start=customStart;end=customEnd}const m=metricsRange(state,iid,start,end,mode==='all');const inRange=v=>{if(mode==='all')return true;const d=String(v||'').slice(0,10);return d>=start&&d<=end};const rows=state.leads.filter(x=>(!iid||x.institutId===iid)&&inRange(x.dateContact));const config=iid?getClientPipelineConfig(state,iid):[];const closed=x=>['won','lost'].includes(config.find(s=>s.label===x.statut)?.type);const due=rows.filter(x=>x.nextActionAt&&inRange(x.nextActionAt)&&!closed(x)).sort((a,b)=>String(a.nextActionAt).localeCompare(String(b.nextActionAt))).slice(0,5);const upcoming=state.leads.filter(x=>(!iid||x.institutId===iid)&&x.rdvAt&&inRange(x.rdvAt)).sort((a,b)=>String(a.rdvAt).localeCompare(String(b.rdvAt))).slice(0,5);return <><div className="dashboard-toolbar"><div><span className="eyebrow">PÉRIODE</span><strong>{rangeLabel(start,end,mode)}</strong></div><div className="period-picker"><select value={mode} onChange={e=>setMode(e.target.value)}><option value="all">Maximum</option><option value="today">Aujourd’hui</option><option value="yesterday">Hier</option><option value="7d">7 derniers jours</option><option value="30d">30 derniers jours</option><option value="month">Ce mois</option><option value="lastMonth">Mois dernier</option><option value="custom">Personnalisé</option></select>{mode==='custom'&&<><input type="date" value={customStart} onChange={e=>setCustomStart(e.target.value)}/><span>→</span><input type="date" value={customEnd} onChange={e=>setCustomEnd(e.target.value)}/></>}</div></div><section className="dashboard-hero"><div><span className="eyebrow light-text">PERFORMANCE</span><h1>{iid?'Vos résultats, sans bruit.':'Pilotez tous vos comptes.'}</h1><p>Une lecture claire de l’acquisition, des rendez-vous et du chiffre d’affaires généré.</p></div><div className="roi-card"><span>Retour sur investissement</span><strong>x{m.roi.toFixed(1)}</strong><small>{m.spend?`${euro(m.revenue)} générés pour ${euro(m.spend)} investis`:'Ajoutez vos dépenses pour calculer le ROI'}</small></div></section><div className="kpi-grid">{[['Dépenses',euro(m.spend)],['Prospects',m.leads],['Rendez-vous',m.rdv],['Clients',m.converted],['CA généré',euro(m.revenue)],['CPL',euro(m.cpl)],['No-show',m.noShow],['Conversion',`${m.conversion.toFixed(1)} %`]].map(([l,v])=><article key={l}><span>{l}</span><strong>{v}</strong></article>)}</div><div className="dashboard-grid"><section className="panel"><span className="eyebrow">À TRAITER</span><h3>Prochaines actions</h3>{due.length?due.map(x=><div className="task-row" key={x.id}><div><strong>{x.prenom} {x.nom}</strong><span>{x.nextActionType||'Relance'} · {fmtDateTime(x.nextActionAt)}</span></div><StatusPill status={x.statut} config={config}/></div>):<Empty text="Aucune action sur cette période."/>}</section><section className="panel"><span className="eyebrow">RENDEZ-VOUS</span><h3>Sur la période</h3>{upcoming.length?upcoming.map(x=><div className="task-row" key={x.id}><div><strong>{x.prenom} {x.nom}</strong><span>{x.rdvType||'Rendez-vous'} · {fmtDateTime(x.rdvAt)}</span></div></div>):<Empty text="Aucun rendez-vous sur cette période."/>}</section></div></>}
function Clients({state,refresh,save,switchCompany}){const[open,setOpen]=useState(false),[selected,setSelected]=useState(null),[f,setF]=useState({name:'',ville:'',contactName:'',email:'',password:''}),[err,setErr]=useState('');async function add(){try{setErr('');await api('/api/instituts',{method:'POST',body:JSON.stringify(f)});setOpen(false);setF({name:'',ville:'',contactName:'',email:'',password:''});refresh()}catch(e){setErr(e.message)}}return <><PageHead title="Comptes clients" desc="Créez et administrez tous les espaces clients Presty."><button className="primary" onClick={()=>setOpen(true)}>Ajouter un compte</button></PageHead><div className="institute-grid">{state.instituts.map(i=><article className="institute-card" key={i.id}><div className="avatar-lg">{i.name[0]}</div><div className="grow"><h3>{i.companyName||i.name}</h3><p>{i.ville||'Ville non renseignée'}</p><small>{i.email}</small></div><div className="client-actions"><button className="ghost small" onClick={()=>switchCompany(i.id)}>Accéder</button><button className="ghost small" onClick={()=>setSelected(i)}>Configurer</button></div></article>)}</div>{open&&<Modal close={()=>setOpen(false)} title="Nouveau compte client"><Field label="Nom de l’entreprise" value={f.name} onChange={v=>setF({...f,name:v})}/><Field label="Ville" value={f.ville} onChange={v=>setF({...f,ville:v})}/><Field label="Nom de l’utilisateur principal" value={f.contactName} onChange={v=>setF({...f,contactName:v})}/><Field label="Email de connexion" type="email" value={f.email} onChange={v=>setF({...f,email:v})}/><Field label="Mot de passe temporaire" type="password" value={f.password} onChange={v=>setF({...f,password:v})}/>{err&&<div className="alert error">{err}</div>}<button className="primary full" onClick={add}>Créer le compte</button></Modal>}{selected&&<ClientAdminDrawer client={selected} state={state} save={save} close={()=>setSelected(null)}/>}</>}

function UsersAdmin({state,refresh}){const[open,setOpen]=useState(false),[selected,setSelected]=useState(null),[f,setF]=useState({name:'',email:'',password:'',role:'setter',institutId:'',accessIds:[]}),[err,setErr]=useState('');const users=state.users.filter(u=>u.role!=='agency_admin');async function create(){try{setErr('');await api('/api/users',{method:'POST',body:JSON.stringify(f)});setOpen(false);setF({name:'',email:'',password:'',role:'setter',institutId:'',accessIds:[]});refresh()}catch(e){setErr(e.message)}}function toggle(id){setF(x=>({...x,accessIds:x.accessIds.includes(id)?x.accessIds.filter(v=>v!==id):[...x.accessIds,id]}))}return <><PageHead title="Utilisateurs" desc="Gérez les accès clients et les assistantes téléphoniques."><button className="primary" onClick={()=>setOpen(true)}>Créer un utilisateur</button></PageHead><section className="panel user-table"><table><thead><tr><th>Utilisateur</th><th>Rôle</th><th>Accès</th><th>Statut</th><th></th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><strong>{u.name}</strong><small>{u.email}</small></td><td><span className="soft-badge">{u.role==='setter'?'Setter téléphonique':'Client'}</span></td><td>{(u.accessIds||[]).map(id=>state.instituts.find(i=>i.id===id)?.name).filter(Boolean).join(', ')||'—'}</td><td>{u.active!==false?'Actif':'Suspendu'}</td><td><button className="ghost small" onClick={()=>setSelected(u)}>Gérer</button></td></tr>)}</tbody></table></section>{open&&<Modal title="Nouvel utilisateur" close={()=>setOpen(false)}><Field label="Nom" value={f.name} onChange={v=>setF({...f,name:v})}/><Field label="Email" type="email" value={f.email} onChange={v=>setF({...f,email:v})}/><Field label="Mot de passe temporaire" type="password" value={f.password} onChange={v=>setF({...f,password:v})}/><SelectField label="Type d’accès" value={f.role} onChange={v=>setF({...f,role:v,accessIds:[],institutId:''})}><option value="setter">Setter téléphonique</option><option value="client">Utilisateur client</option></SelectField>{f.role==='client'?<SelectField label="Compte client" value={f.institutId} onChange={v=>setF({...f,institutId:v,accessIds:[v]})}><option value="">Sélectionner…</option>{state.instituts.map(i=><option value={i.id} key={i.id}>{i.name}</option>)}</SelectField>:<div className="access-list"><span className="field-label">Comptes autorisés</span>{state.instituts.map(i=><label key={i.id}><input type="checkbox" checked={f.accessIds.includes(i.id)} onChange={()=>toggle(i.id)}/><span>{i.name}</span></label>)}</div>}{err&&<div className="alert error">{err}</div>}<button className="primary full" onClick={create}>Créer l’accès</button></Modal>}{selected&&<AdminUserDrawer user={selected} state={state} refresh={refresh} close={()=>setSelected(null)}/>}</>}
function AdminUserDrawer({user,state,refresh,close}){const[name,setName]=useState(user.name||''),[active,setActive]=useState(user.active!==false),[accessIds,setAccess]=useState(user.accessIds||[]),[password,setPassword]=useState(''),[msg,setMsg]=useState(''),[err,setErr]=useState('');function toggle(id){setAccess(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id])}async function saveUser(){try{setErr('');await api('/api/users',{method:'PATCH',body:JSON.stringify({id:user.id,name,active,accessIds})});setMsg('Accès mis à jour.');refresh()}catch(e){setErr(e.message)}}async function reset(){try{setErr('');await api('/api/users/reset-password',{method:'POST',body:JSON.stringify({id:user.id,newPassword:password})});setMsg('Mot de passe temporaire appliqué.');setPassword('')}catch(e){setErr(e.message)}}return <Drawer title={user.name} close={close}><div className="drawer-section"><span className="eyebrow">ACCÈS UTILISATEUR</span><h3>Gérer le compte</h3><Field label="Nom" value={name} onChange={setName}/><Field label="Email" value={user.email} disabled/><label className="toggle-row"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/><span>Compte actif</span></label>{user.role==='setter'&&<div className="access-list"><span className="field-label">Comptes clients autorisés</span>{state.instituts.map(i=><label key={i.id}><input type="checkbox" checked={accessIds.includes(i.id)} onChange={()=>toggle(i.id)}/><span>{i.name}</span></label>)}</div>}<button className="primary full" onClick={saveUser}>Enregistrer les accès</button></div><div className="drawer-section"><span className="eyebrow">SÉCURITÉ</span><h3>Mot de passe temporaire</h3><p className="muted">L’admin peut définir un nouveau mot de passe temporaire si l’utilisateur est bloqué.</p><Field label="Nouveau mot de passe" type="password" value={password} onChange={setPassword} placeholder="8 caractères minimum"/><button className="ghost full" onClick={reset} disabled={password.length<8}>Définir le mot de passe</button>{err&&<div className="alert error">{err}</div>}{msg&&<div className="alert success">{msg}</div>}</div></Drawer>}

function ClientAdminDrawer({client,state,save,close}){const integration=(state.integrations||[]).find(x=>x.institutId===client.id&&x.provider==='ghl')||{id:uid(),institutId:client.id,provider:'ghl',locationId:'',forms:[]};const[locationId,setLocationId]=useState(integration.locationId||'');const[forms,setForms]=useState(integration.forms||[]);function saveGhl(){const next={...integration,locationId,forms};save({...state,integrations:[...(state.integrations||[]).filter(x=>x.id!==integration.id),next]})}return <Drawer close={close} title={client.name}><div className="drawer-section"><span className="eyebrow">GOHIGHLEVEL</span><h3>Routage automatique des leads</h3><p className="muted">Associez le Location ID du sous-compte GHL. Le webhook générique route ensuite automatiquement chaque formulaire vers ce compte.</p><Field label="Location ID" value={locationId} onChange={setLocationId}/><div className="mapping-list">{forms.map((f,i)=><div className="mapping-row" key={i}><input placeholder="Form ID" value={f.formId||''} onChange={e=>setForms(forms.map((x,j)=>j===i?{...x,formId:e.target.value}:x))}/><input placeholder="Nom du formulaire" value={f.formName||''} onChange={e=>setForms(forms.map((x,j)=>j===i?{...x,formName:e.target.value}:x))}/><input placeholder="Catégorie" value={f.category||''} onChange={e=>setForms(forms.map((x,j)=>j===i?{...x,category:e.target.value}:x))}/><button onClick={()=>setForms(forms.filter((_,j)=>j!==i))}>×</button></div>)}</div><button className="ghost" onClick={()=>setForms([...forms,{formId:'',formName:'',category:'',service:''}])}>+ Ajouter un formulaire</button><button className="primary full" onClick={saveGhl}>Enregistrer l’intégration</button><div className="code-note"><code>/api/webhook/ghl</code><small>Header requis : x-webhook-secret</small></div></div></Drawer>}

function Contacts({state,iid,save}){const[q,setQ]=useState(''),[category,setCategory]=useState(''),[status,setStatus]=useState(''),[form,setForm]=useState(''),[selected,setSelected]=useState(null),[openNew,setOpenNew]=useState(false);const categories=getClientCategories(state,iid),pipeline=getClientPipeline(state,iid),config=getClientPipelineConfig(state,iid);const forms=[...new Set(state.leads.filter(x=>x.institutId===iid).map(x=>x.formName||x.source).filter(Boolean))];let rows=state.leads.filter(x=>x.institutId===iid&&(`${x.prenom} ${x.nom} ${x.email} ${x.telephone}`).toLowerCase().includes(q.toLowerCase()));if(category)rows=rows.filter(x=>x.category===category);if(status)rows=rows.filter(x=>x.statut===status);if(form)rows=rows.filter(x=>(x.formName||x.source)===form);rows.sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));return <><PageHead title="Contacts" desc="Votre base de contacts centralisée. Le suivi commercial se fait dans le CRM."><button className="primary" onClick={()=>setOpenNew(true)}>+ Ajouter un contact</button></PageHead><div className="directory-filters"><input className="search-input" placeholder="Rechercher un contact…" value={q} onChange={e=>setQ(e.target.value)}/><select value={category} onChange={e=>setCategory(e.target.value)}><option value="">Toutes les catégories</option>{categories.map(c=><option key={c}>{c}</option>)}</select><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Tous les statuts</option>{pipeline.map(s=><option key={s}>{s}</option>)}</select><select value={form} onChange={e=>setForm(e.target.value)}><option value="">Tous les formulaires</option>{forms.map(f=><option key={f}>{f}</option>)}</select><button className="ghost" onClick={()=>{setQ('');setCategory('');setStatus('');setForm('')}}>Réinitialiser</button></div><section className="panel contact-directory responsive-table"><table><thead><tr><th>Contact</th><th>Téléphone</th><th>Email</th><th>Formulaire</th><th>Catégorie</th><th>Statut</th></tr></thead><tbody>{rows.map(x=><tr key={x.id} onClick={()=>setSelected(x.id)}><td data-label="Contact"><strong>{x.prenom} {x.nom}</strong></td><td data-label="Téléphone">{x.telephone||'—'}</td><td data-label="Email">{x.email||'—'}</td><td data-label="Formulaire">{x.formName||x.source||'—'}</td><td data-label="Catégorie">{x.category}</td><td data-label="Statut"><StatusPill status={x.statut} config={config}/></td></tr>)}</tbody></table></section>{openNew&&<NewLead state={state} iid={iid} save={save} close={()=>setOpenNew(false)}/>} {selected&&<ContactDrawer lead={state.leads.find(x=>x.id===selected)} state={state} save={save} close={()=>setSelected(null)} iid={iid}/>}</>}
function CRM({state,iid,admin,save}){const[view,setView]=useState('list'),[q,setQ]=useState(''),[periodType,setPeriodType]=useState('all'),[month,setMonth]=useState(new Date().toISOString().slice(0,7)),[category,setCategory]=useState(''),[status,setStatus]=useState(''),[form,setForm]=useState(''),[selected,setSelected]=useState(null),[openNew,setOpenNew]=useState(false);const categories=iid?getClientCategories(state,iid):[];const pipeline=iid?getClientPipeline(state,iid):DEFAULT_PIPELINE;const pipelineConfig=iid?getClientPipelineConfig(state,iid):[];const forms=[...new Set(state.leads.filter(x=>!iid||x.institutId===iid).map(x=>x.formName||x.source).filter(Boolean))];let rows=state.leads.filter(x=>(!iid||x.institutId===iid)&&(`${x.prenom} ${x.nom} ${x.email} ${x.telephone}`).toLowerCase().includes(q.toLowerCase()));if(periodType==='month')rows=rows.filter(x=>monthKey(x.dateContact)===month);if(periodType==='7d'){const d=new Date(Date.now()-7*86400000);rows=rows.filter(x=>new Date(x.dateContact)>=d)}if(category)rows=rows.filter(x=>x.category===category);if(status)rows=rows.filter(x=>x.statut===status);if(form)rows=rows.filter(x=>(x.formName||x.source)===form);rows.sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));async function patch(id,p){const type=p.statut?pipelineConfig.find(s=>s.label===p.statut)?.type:null;const next={...state,leads:state.leads.map(x=>x.id===id?{...x,...p,converted:type?type==='won':x.converted,updatedAt:nowIso()}:x)};await save(next)}return <><PageHead title="CRM" desc="Votre espace de travail commercial : appels, relances, rendez-vous et conversions."><div className="segmented"><button className={view==='list'?'active':''} onClick={()=>setView('list')}>Liste</button><button className={view==='pipeline'?'active':''} onClick={()=>setView('pipeline')}>Pipeline</button></div>{iid&&<button className="primary" onClick={()=>setOpenNew(true)}>Nouveau prospect</button>}</PageHead><div className="crm-filterbar"><input placeholder="Rechercher…" value={q} onChange={e=>setQ(e.target.value)}/><select value={periodType} onChange={e=>setPeriodType(e.target.value)}><option value="all">Toutes les périodes</option><option value="7d">7 derniers jours</option><option value="month">Mois précis</option></select>{periodType==='month'&&<input type="month" value={month} onChange={e=>setMonth(e.target.value)}/>}<select value={category} onChange={e=>setCategory(e.target.value)}><option value="">Toutes les catégories</option>{categories.map(c=><option key={c}>{c}</option>)}</select><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Tous les statuts</option>{pipeline.map(s=><option key={s}>{s}</option>)}</select><select value={form} onChange={e=>setForm(e.target.value)}><option value="">Tous les formulaires</option>{forms.map(s=><option key={s}>{s}</option>)}</select><button className="ghost" onClick={()=>{setQ('');setPeriodType('all');setCategory('');setStatus('');setForm('')}}>Réinitialiser</button></div>{view==='list'?<CRMList rows={rows} pipeline={pipeline} pipelineConfig={pipelineConfig} categories={categories} patch={patch} open={id=>setSelected(id)}/>:<Pipeline rows={rows} pipeline={pipeline} pipelineConfig={pipelineConfig} patch={patch} open={id=>setSelected(id)}/>} {openNew&&<NewLead state={state} iid={iid} save={save} close={()=>setOpenNew(false)}/>} {selected&&<ContactDrawer lead={state.leads.find(x=>x.id===selected)} state={state} save={save} close={()=>setSelected(null)} iid={iid}/>}</>}
function CRMList({rows,pipeline,pipelineConfig,categories,patch,open}){return <section className="panel table-wrap editable-table crm-list-simple responsive-table"><table><thead><tr><th>Contact</th><th>Téléphone</th><th>Catégorie</th><th>Statut</th><th>RDV</th><th>Valeur</th><th>Dernier commentaire</th><th></th></tr></thead><tbody>{rows.map(x=>{const last=(x.comments||[]).at(-1);return <tr key={x.id}><td data-label="Contact" className="clickable-cell" onClick={()=>open(x.id)}><strong>{x.prenom} {x.nom}</strong><small>{x.email}</small></td><td data-label="Téléphone"><a href={telHref(x.telephone)}>{x.telephone||'—'}</a></td><td data-label="Catégorie"><select value={x.category} onChange={e=>patch(x.id,{category:e.target.value})}>{categories.map(c=><option key={c}>{c}</option>)}</select></td><td data-label="Statut"><select className="status-select" value={x.statut} onChange={e=>patch(x.id,{statut:e.target.value})}>{pipeline.map(s=><option key={s}>{s}</option>)}</select><StatusPill status={x.statut} config={pipelineConfig}/></td><td data-label="RDV"><input type="datetime-local" value={x.rdvAt?.slice(0,16)||''} onChange={e=>{const booked=pipelineConfig.find(s=>s.type==='appointment_booked')?.label||'RDV fixé';patch(x.id,{rdvAt:e.target.value,statut:e.target.value?booked:x.statut})}}/></td><td data-label="Valeur"><input className="money-input" type="number" value={x.value||''} onChange={e=>patch(x.id,{value:Number(e.target.value)})}/></td><td data-label="Dernier commentaire" className="comment-readonly" onClick={()=>open(x.id)}>{last?<><span>{last.text}</span><small>{fmtDateTime(last.createdAt)}</small></>:<span className="muted">Aucun commentaire</span>}</td><td data-label="Fiche"><button className="open-contact" onClick={()=>open(x.id)}>Voir la fiche <span>›</span></button></td></tr>})}</tbody></table></section>}
function Pipeline({rows,pipeline,pipelineConfig,patch,open}){return <div className="kanban crm-kanban">{pipeline.map(s=><section className="column" key={s} onDragOver={e=>e.preventDefault()} onDrop={e=>patch(e.dataTransfer.getData('lead'),{statut:s})}><h3><StatusPill status={s} config={pipelineConfig}/><b>{rows.filter(x=>x.statut===s).length}</b></h3>{rows.filter(x=>x.statut===s).map(x=><article className="lead crm-card" key={x.id} draggable onDragStart={e=>e.dataTransfer.setData('lead',x.id)} onClick={()=>open(x.id)}><div className="card-top"><strong>{x.prenom} {x.nom}</strong><span className="value-pill">{euro(x.value)}</span></div><small>{x.formName||x.source||x.category}</small>{x.nextActionAt&&<div className="next-action"><span>{x.nextActionType||'Relance'}</span><b>{fmtDateTime(x.nextActionAt)}</b></div>}{x.rdvAt&&<div className="rdv-chip">RDV · {fmtDateTime(x.rdvAt)}</div>}{(x.comments||[]).length>0&&<p className="comment-preview">{x.comments.at(-1).text}</p>}<div className="card-actions"><a href={telHref(x.telephone)} onClick={e=>e.stopPropagation()}>Appeler</a><a href={waHref(x.telephone)} target="_blank" onClick={e=>e.stopPropagation()}>WhatsApp</a></div></article>)}</section>)}</div>}
function NewLead({state,iid,save,close}){const cats=getClientCategories(state,iid),pipeline=getClientPipeline(state,iid),[f,setF]=useState({prenom:'',nom:'',telephone:'',email:'',category:cats[0]||'Autres',formName:'Manuel',statut:pipeline[0]||'Nouveau'});async function add(){if(!f.prenom&&!f.nom)return;const lead={...f,id:uid(),institutId:iid,dateContact:today(),source:f.formName,channel:'Manuel',comments:[],activity:[{id:uid(),type:'Création',text:'Prospect ajouté manuellement',createdAt:nowIso()}],value:0,converted:false,additionalInfo:{},updatedAt:nowIso()};await save({...state,leads:[lead,...state.leads]});close()}return <Modal title="Nouveau prospect" close={close}><div className="form-grid"><Field label="Prénom" value={f.prenom} onChange={v=>setF({...f,prenom:v})}/><Field label="Nom" value={f.nom} onChange={v=>setF({...f,nom:v})}/><Field label="Téléphone" value={f.telephone} onChange={v=>setF({...f,telephone:v})}/><Field label="Email" value={f.email} onChange={v=>setF({...f,email:v})}/><SelectField label="Catégorie" value={f.category} onChange={v=>setF({...f,category:v})}>{cats.map(c=><option key={c}>{c}</option>)}</SelectField><Field label="Source / formulaire" value={f.formName} onChange={v=>setF({...f,formName:v})}/></div><button className="primary full" onClick={add}>Ajouter au CRM</button></Modal>}
function ContactDrawer({lead,state,save,close,iid}){const[comment,setComment]=useState('');if(!lead)return null;const categories=getClientCategories(state,iid),pipeline=getClientPipeline(state,iid),pipelineConfig=getClientPipelineConfig(state,iid);async function update(p){await save({...state,leads:state.leads.map(x=>x.id===lead.id?{...x,...p,converted:p.statut?(pipelineConfig.find(s=>s.label===p.statut)?.type==='won'):x.converted,updatedAt:nowIso()}:x)})}async function log(type){await update({activity:[...(lead.activity||[]),{id:uid(),type,text:`${type} depuis la fiche contact`,createdAt:nowIso()}]})}async function addComment(){if(!comment.trim())return;await update({comments:[...(lead.comments||[]),{id:uid(),text:comment.trim(),createdAt:nowIso(),author:'Utilisateur'}]});setComment('')}return <Drawer title="Fiche contact" close={close}><div className="contact-summary"><div><StatusPill status={lead.statut} config={pipelineConfig}/><h2>{lead.prenom} {lead.nom}</h2><p>{lead.formName||lead.typeSoin||'Contact'}</p></div><div className="contact-actions"><a className="primary small" href={telHref(lead.telephone)} onClick={()=>log('Appel')}>☎ Appeler</a><a className="ghost small" href={waHref(lead.telephone)} target="_blank" onClick={()=>log('WhatsApp')}>WhatsApp</a><a className="ghost small" href={smsHref(lead.telephone)} onClick={()=>log('SMS')}>Message</a></div></div><div className="drawer-grid"><Field label="Téléphone" value={lead.telephone} onChange={v=>update({telephone:v})}/><Field label="Email" value={lead.email} onChange={v=>update({email:v})}/><SelectField label="Catégorie" value={lead.category} onChange={v=>update({category:v})}>{categories.map(c=><option key={c}>{c}</option>)}</SelectField><Field label="Formulaire" value={lead.formName||lead.source} onChange={v=>update({formName:v,source:v})}/><SelectField label="Statut" value={lead.statut} onChange={v=>update({statut:v})}>{pipeline.map(s=><option key={s}>{s}</option>)}</SelectField><Field label="Valeur (€)" type="number" value={lead.value||''} onChange={v=>update({value:Number(v)})}/><SelectField label="Prochaine action" value={lead.nextActionType} onChange={v=>update({nextActionType:v})}><option value="">Aucune</option>{ACTION_TYPES.map(a=><option key={a}>{a}</option>)}</SelectField><Field label="Date de la prochaine action" type="datetime-local" value={lead.nextActionAt?.slice(0,16)||''} onChange={v=>update({nextActionAt:v})}/><Field label="Rendez-vous" type="datetime-local" value={lead.rdvAt?.slice(0,16)||''} onChange={v=>update({rdvAt:v,statut:v?(pipelineConfig.find(s=>s.type==='appointment_booked')?.label||lead.statut):lead.statut})}/><Field label="Type de rendez-vous" value={lead.rdvType} onChange={v=>update({rdvType:v})}/></div>{Object.keys(lead.additionalInfo||{}).length>0&&<div className="drawer-section"><span className="eyebrow">INFORMATIONS COMPLÉMENTAIRES</span><h3>Réponses du formulaire</h3><div className="additional-info">{Object.entries(lead.additionalInfo).map(([k,v])=><div key={k}><span>{k.replace(/_/g,' ')}</span><strong>{String(v)}</strong></div>)}</div></div>}<div className="drawer-section"><span className="eyebrow">COMMENTAIRES</span><div className="comment-composer"><textarea placeholder="Ajouter un commentaire commercial…" value={comment} onChange={e=>setComment(e.target.value)}/><button className="primary" onClick={addComment}>Ajouter</button></div><div className="timeline">{[...(lead.comments||[])].reverse().map(c=><div className="timeline-item" key={c.id}><span className="timeline-dot"/><div><strong>{c.author||'Utilisateur'}</strong><p>{c.text}</p><small>{fmtDateTime(c.createdAt)}</small></div></div>)}</div></div><div className="drawer-section"><span className="eyebrow">HISTORIQUE</span><div className="timeline compact">{[...(lead.activity||[])].reverse().map(a=><div className="timeline-item" key={a.id}><span className="timeline-dot"/><div><strong>{a.type}</strong><p>{a.text}</p><small>{fmtDateTime(a.createdAt)}</small></div></div>)}</div></div>{(lead.ghlLocationId||lead.ghlFormId)&&<div className="source-meta"><strong>Origine GoHighLevel</strong><span>Location ID : {lead.ghlLocationId||'—'}</span><span>Form ID : {lead.ghlFormId||'—'}</span><span>Canal : {lead.channel||'—'}</span></div>}</Drawer>}

function Appointments({state,iid,save}){const[filter,setFilter]=useState('upcoming'),[date,setDate]=useState(today()),[selected,setSelected]=useState(null);const config=getClientPipelineConfig(state,iid);const startDay=d=>new Date(`${d}T00:00:00`),endDay=d=>new Date(`${d}T23:59:59`);let rows=state.leads.filter(x=>x.institutId===iid&&x.rdvAt);const now=new Date();if(filter==='today')rows=rows.filter(x=>{const d=new Date(x.rdvAt);return d>=startDay(today())&&d<=endDay(today())});if(filter==='tomorrow'){const d=new Date(Date.now()+86400000).toISOString().slice(0,10);rows=rows.filter(x=>new Date(x.rdvAt)>=startDay(d)&&new Date(x.rdvAt)<=endDay(d))}if(filter==='week'){const end=new Date(Date.now()+7*86400000);rows=rows.filter(x=>new Date(x.rdvAt)>=now&&new Date(x.rdvAt)<=end)}if(filter==='date')rows=rows.filter(x=>new Date(x.rdvAt)>=startDay(date)&&new Date(x.rdvAt)<=endDay(date));if(filter==='upcoming')rows=rows.filter(x=>new Date(x.rdvAt)>=new Date(Date.now()-3600000));if(filter==='past')rows=rows.filter(x=>new Date(x.rdvAt)<now);rows.sort((a,b)=>String(a.rdvAt).localeCompare(String(b.rdvAt)));const groups=rows.reduce((o,x)=>{const k=x.rdvAt.slice(0,10);(o[k]??=[]).push(x);return o},{});return <><PageHead title="Rendez-vous" desc="Une vue simple de votre agenda commercial, organisée jour par jour."><div className="appointment-filters"><button className={filter==='today'?'active':''} onClick={()=>setFilter('today')}>Aujourd’hui</button><button className={filter==='tomorrow'?'active':''} onClick={()=>setFilter('tomorrow')}>Demain</button><button className={filter==='week'?'active':''} onClick={()=>setFilter('week')}>7 jours</button><button className={filter==='upcoming'?'active':''} onClick={()=>setFilter('upcoming')}>À venir</button><button className={filter==='past'?'active':''} onClick={()=>setFilter('past')}>Passés</button><button className={filter==='date'?'active':''} onClick={()=>setFilter('date')}>Date</button>{filter==='date'&&<input type="date" value={date} onChange={e=>setDate(e.target.value)}/>}</div></PageHead><div className="appointment-list">{Object.keys(groups).length?Object.entries(groups).map(([day,items])=><section className="appointment-day" key={day}><div className="appointment-date"><strong>{new Date(`${day}T12:00:00`).toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</strong><span>{items.length} rendez-vous</span></div><div className="appointment-cards">{items.map(x=><article key={x.id} onClick={()=>setSelected(x.id)}><div className="appointment-time">{new Date(x.rdvAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</div><div className="appointment-person"><strong>{x.prenom} {x.nom}</strong><span>{x.rdvType||x.typeSoin||x.formName||'Rendez-vous'}</span></div><StatusPill status={x.statut} config={config}/><div className="row-actions"><a href={telHref(x.telephone)} onClick={e=>e.stopPropagation()}>☎</a><a href={waHref(x.telephone)} target="_blank" onClick={e=>e.stopPropagation()}>WA</a></div></article>)}</div></section>):<Empty text="Aucun rendez-vous pour cette période."/>}</div>{selected&&<ContactDrawer lead={state.leads.find(x=>x.id===selected)} state={state} save={save} close={()=>setSelected(null)} iid={iid}/>}</>}
function Ads({state,iid}){const period=new Date().toISOString().slice(0,7);const ex=state.expenses.filter(x=>(!iid||x.institutId===iid)&&`${x.year}-${String(x.month).padStart(2,'0')}`===period);const total=ex.reduce((s,x)=>s+Number(x.amount||0),0);return <><PageHead title="Publicité" desc="Suivez les investissements et préparez la connexion Meta Ads."/><div className="dashboard-grid"><section className="panel"><span className="eyebrow">DÉPENSES DU MOIS</span><h3>{euro(total)} investis</h3>{ex.length?ex.map(x=><div className="category-row" key={x.id}><div><strong>{x.campaign||x.category}</strong><span>{x.category}</span></div><b>{euro(x.amount)}</b></div>):<Empty text="Aucune dépense renseignée."/>}</section><section className="panel integration-card"><span className="eyebrow">META ADS</span><h3>Connexion du compte publicitaire</h3><p>La connexion OAuth Meta sera branchée ici pour afficher campagnes, dépenses, leads et CPL.</p><span className="soft-badge">À connecter</span></section></div></>}

function Stats({state,iid}){const[mode,setMode]=useState('month'),[customStart,setCustomStart]=useState(today()),[customEnd,setCustomEnd]=useState(today());const now=new Date();const ymd=d=>d.toISOString().slice(0,10);let start='',end='';if(mode==='today'){start=end=today()}else if(mode==='yesterday'){const d=new Date(now);d.setDate(d.getDate()-1);start=end=ymd(d)}else if(mode==='7d'){const d=new Date(now);d.setDate(d.getDate()-6);start=ymd(d);end=today()}else if(mode==='30d'){const d=new Date(now);d.setDate(d.getDate()-29);start=ymd(d);end=today()}else if(mode==='month'){start=`${today().slice(0,7)}-01`;end=today()}else if(mode==='lastMonth'){const d=new Date(now.getFullYear(),now.getMonth()-1,1),e=new Date(now.getFullYear(),now.getMonth(),0);start=ymd(d);end=ymd(e)}else if(mode==='custom'){start=customStart;end=customEnd}const inRange=v=>{if(mode==='all')return true;const d=String(v||'').slice(0,10);return d>=start&&d<=end};const m=metricsRange(state,iid,start,end,mode==='all');const rows=state.leads.filter(x=>x.institutId===iid&&inRange(x.dateContact));const spendRows=state.spend.filter(x=>x.institutId===iid&&(mode==='all'||(`${x.annee}-${String(x.mois).padStart(2,'0')}-01`>=start.slice(0,7)+'-01'&&`${x.annee}-${String(x.mois).padStart(2,'0')}-01`<=end.slice(0,7)+'-31')));const byForm=[...new Set(rows.map(x=>x.formName||x.source))].filter(Boolean).map(form=>({form,count:rows.filter(x=>(x.formName||x.source)===form).length,ca:rows.filter(x=>(x.formName||x.source)===form&&(x.converted||x.statut==='Gagné')).reduce((sum,x)=>sum+Number(x.value||0),0)})).sort((a,b)=>b.count-a.count);const byCategory=[...new Set(rows.map(x=>x.category).filter(Boolean))].map(category=>({category,count:rows.filter(x=>x.category===category).length,clients:rows.filter(x=>x.category===category&&x.converted).length,ca:rows.filter(x=>x.category===category&&x.converted).reduce((sum,x)=>sum+Number(x.value||0),0)})).sort((a,b)=>b.ca-a.ca);return <><PageHead title="Statistiques" desc="Analysez vos résultats en détail sur la période de votre choix."/><div className="dashboard-toolbar stats-toolbar"><div><span className="eyebrow">PÉRIODE ANALYSÉE</span><strong>{rangeLabel(start,end,mode)}</strong></div><div className="period-picker"><select value={mode} onChange={e=>setMode(e.target.value)}><option value="all">Maximum</option><option value="today">Aujourd’hui</option><option value="yesterday">Hier</option><option value="7d">7 derniers jours</option><option value="30d">30 derniers jours</option><option value="month">Ce mois</option><option value="lastMonth">Mois dernier</option><option value="custom">Personnalisé</option></select>{mode==='custom'&&<><input type="date" value={customStart} onChange={e=>setCustomStart(e.target.value)}/><span>→</span><input type="date" value={customEnd} onChange={e=>setCustomEnd(e.target.value)}/></>}</div></div><div className="kpi-grid">{[['Prospects',m.leads],['RDV',m.rdv],['No-show',m.noShow],['Clients',m.converted],['CA',euro(m.revenue)],['CPL',euro(m.cpl)],['Conversion',`${m.conversion.toFixed(1)} %`],['ROI',`x${m.roi.toFixed(1)}`]].map(([a,b])=><article key={a}><span>{a}</span><strong>{b}</strong></article>)}</div><div className="stats-detail-grid"><section className="panel"><span className="eyebrow">FORMULAIRES</span><h3>Origine des prospects</h3>{byForm.length?byForm.map(x=><div className="category-row" key={x.form}><div><strong>{x.form}</strong><span>{x.count} prospect{x.count>1?'s':''}</span></div><b>{euro(x.ca)}</b></div>):<Empty text="Aucune donnée sur cette période."/>}</section><section className="panel"><span className="eyebrow">CATÉGORIES</span><h3>Performance commerciale</h3>{byCategory.length?byCategory.map(x=><div className="category-row" key={x.category}><div><strong>{x.category}</strong><span>{x.count} prospects · {x.clients} clients</span></div><b>{euro(x.ca)}</b></div>):<Empty text="Aucune donnée sur cette période."/>}</section></div></>}
function Settings({state,iid,admin,user,save}){const[section,setSection]=useState(admin?'agency':'company');if(admin)return <><PageHead title="Paramètres" desc="Informations et sécurité du compte agence."/><div className="settings-layout"><aside className="settings-nav">{[['agency','Agence'],['security','Sécurité']].map(([id,label])=><button className={section===id?'active':''} key={id} onClick={()=>setSection(id)}>{label}</button>)}</aside><div>{section==='agency'&&<section className="panel"><span className="eyebrow">COMPTE AGENCE</span><h3>Presty Digital</h3><div className="info-list"><span>Administrateur <b>{user.name}</b></span><span>Email <b>{user.email}</b></span></div><p className="muted">Les réglages propres à chaque client se font depuis « Comptes clients » puis « Configurer ». L’administration agence reste volontairement simple.</p></section>}{section==='security'&&<UserSettings user={user}/>}</div></div></>;const client=state.instituts.find(i=>i.id===iid);return <><PageHead title="Paramètres" desc="Gérez votre entreprise, votre accès et les réglages du CRM."/><div className="settings-layout"><aside className="settings-nav">{[['company','Compte'],['user','Utilisateur'],['crm','CRM'],['integrations','Intégrations'],['notifications','Notifications']].map(([id,label])=><button className={section===id?'active':''} key={id} onClick={()=>setSection(id)}>{label}</button>)}</aside><div>{section==='company'&&<CompanySettings client={client} state={state} save={save}/>} {section==='user'&&<UserSettings user={user}/>} {section==='crm'&&<CRMSettings client={client} state={state} save={save}/>} {section==='integrations'&&<IntegrationSettings state={state} iid={iid}/>} {section==='notifications'&&<section className="panel"><span className="eyebrow">NOTIFICATIONS</span><h3>Préférences de notification</h3><p className="muted">Les alertes nouveau prospect, relance et rendez-vous seront configurables ici.</p><span className="soft-badge">Bientôt disponible</span></section>}</div></div></>}
function CompanySettings({client,state,save}){const[f,setF]=useState({name:client?.companyName||client?.name||'',ville:client?.ville||'',email:client?.email||'',telephone:client?.telephone||'',address:client?.address||'',website:client?.website||''}),[msg,setMsg]=useState('');async function submit(){await save({...state,instituts:state.instituts.map(i=>i.id===client.id?{...i,...f,companyName:f.name,name:f.name}:i)});setMsg('Informations enregistrées.')}return <section className="panel"><span className="eyebrow">COMPTE ENTREPRISE</span><h3>{f.name}</h3><div className="form-grid"><Field label="Nom de l’entreprise" value={f.name} onChange={v=>setF({...f,name:v})}/><Field label="Ville" value={f.ville} onChange={v=>setF({...f,ville:v})}/><Field label="Email" value={f.email} onChange={v=>setF({...f,email:v})}/><Field label="Téléphone" value={f.telephone} onChange={v=>setF({...f,telephone:v})}/><Field label="Adresse" value={f.address} onChange={v=>setF({...f,address:v})}/><Field label="Site internet" value={f.website} onChange={v=>setF({...f,website:v})}/></div>{msg&&<div className="alert success">{msg}</div>}<div className="settings-savebar"><button className="primary" onClick={submit}>Enregistrer</button></div></section>}
function UserSettings({user}){const[currentPassword,setCurrent]=useState(''),[newPassword,setNew]=useState(''),[msg,setMsg]=useState(''),[err,setErr]=useState('');async function change(){try{setErr('');await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword,newPassword})});setMsg('Mot de passe modifié.');setCurrent('');setNew('')}catch(e){setErr(e.message)}}return <section className="panel"><span className="eyebrow">UTILISATEUR</span><h3>{user.name}</h3><div className="info-list"><span>Email <b>{user.email}</b></span><span>Type d’accès <b>{user.role==='setter'?'Setter':'Client'}</b></span></div><div className="settings-password"><Field label="Mot de passe actuel" type="password" value={currentPassword} onChange={setCurrent}/><Field label="Nouveau mot de passe" type="password" value={newPassword} onChange={setNew}/></div>{err&&<div className="alert error">{err}</div>}{msg&&<div className="alert success">{msg}</div>}<button className="primary" onClick={change}>Modifier le mot de passe</button></section>}
function CRMSettings({client,state,save}){const[categories,setCategories]=useState(client?.categories||[]),[newCat,setNewCat]=useState(''),[steps,setSteps]=useState(client?.pipelineConfig||getClientPipelineConfig(state,client.id)),[newStep,setNewStep]=useState({label:'',color:'#2D45F9',type:'prospect'});async function persistCategories(next){setCategories(next);await save({...state,instituts:state.instituts.map(i=>i.id===client.id?{...i,categories:next}:i)})}async function persistSteps(next){setSteps(next);await save({...state,instituts:state.instituts.map(i=>i.id===client.id?{...i,pipelineConfig:next,pipeline:next.map(s=>s.label)}:i)})}async function patchStep(id,p){const previous=steps.find(s=>s.id===id);const nextSteps=steps.map(s=>s.id===id?{...s,...p}:s);setSteps(nextSteps);const nextState={...state,instituts:state.instituts.map(i=>i.id===client.id?{...i,pipelineConfig:nextSteps,pipeline:nextSteps.map(s=>s.label)}:i),leads:p.label&&previous?.label!==p.label?state.leads.map(l=>l.institutId===client.id&&l.statut===previous.label?{...l,statut:p.label,updatedAt:nowIso()}:l):state.leads};await save(nextState)}function move(id,dir){const i=steps.findIndex(s=>s.id===id),j=i+dir;if(i<0||j<0||j>=steps.length)return;const next=[...steps];[next[i],next[j]]=[next[j],next[i]];persistSteps(next)}return <section className="panel crm-settings-panel"><span className="eyebrow">CRM</span><h3>Catégories personnalisées</h3><p className="muted">Elles sont utilisées dans les filtres, les fiches et les statistiques.</p><div className="tag-list">{categories.map(c=><span key={c}>{c}<button onClick={()=>persistCategories(categories.filter(x=>x!==c))}>×</button></span>)}</div><div className="inline-add"><input placeholder="Nouvelle catégorie" value={newCat} onChange={e=>setNewCat(e.target.value)}/><button className="primary" onClick={()=>{const v=newCat.trim();if(v&&!categories.includes(v)){persistCategories([...categories,v]);setNewCat('')}}}>Ajouter</button></div><div className="pipeline-editor"><span className="eyebrow">PIPELINE COMMERCIAL</span><h3>Étapes, couleurs et logique métier</h3><p className="muted">Vous pouvez adapter librement les libellés. Le type métier permet à Presty de continuer à calculer les RDV, no-show, clients gagnés et pertes correctement.</p>{steps.map((st,index)=><div className="pipeline-edit-row" key={st.id}><input className="stage-label" value={st.label} onChange={e=>patchStep(st.id,{label:e.target.value})}/><input className="color-picker" type="color" value={st.color||'#2D45F9'} onChange={e=>patchStep(st.id,{color:e.target.value})}/><select value={st.type||'prospect'} onChange={e=>patchStep(st.id,{type:e.target.value})}><option value="prospect">Prospect</option><option value="contact">En échange / appel</option><option value="appointment_booked">RDV fixé</option><option value="appointment_completed">RDV réalisé</option><option value="no_show">No-show</option><option value="won">Gagné</option><option value="lost">Perdu</option></select><StatusPill status={st.label} config={steps}/><div className="stage-actions"><button disabled={index===0} onClick={()=>move(st.id,-1)}>↑</button><button disabled={index===steps.length-1} onClick={()=>move(st.id,1)}>↓</button><button className="danger" onClick={()=>{const remaining=steps.filter(x=>x.id!==st.id);if(!remaining.length)return;const fallback=remaining[0].label;setSteps(remaining);save({...state,instituts:state.instituts.map(i=>i.id===client.id?{...i,pipelineConfig:remaining,pipeline:remaining.map(s=>s.label)}:i),leads:state.leads.map(l=>l.institutId===client.id&&l.statut===st.label?{...l,statut:fallback,updatedAt:nowIso()}:l)})}}>×</button></div></div>)}<div className="pipeline-add-row"><input placeholder="Nouvelle étape" value={newStep.label} onChange={e=>setNewStep({...newStep,label:e.target.value})}/><input type="color" value={newStep.color} onChange={e=>setNewStep({...newStep,color:e.target.value})}/><select value={newStep.type} onChange={e=>setNewStep({...newStep,type:e.target.value})}><option value="prospect">Prospect</option><option value="contact">En échange / appel</option><option value="appointment_booked">RDV fixé</option><option value="appointment_completed">RDV réalisé</option><option value="no_show">No-show</option><option value="won">Gagné</option><option value="lost">Perdu</option></select><button className="primary" onClick={()=>{const label=newStep.label.trim();if(label){persistSteps([...steps,{...newStep,id:uid(),label}]);setNewStep({label:'',color:'#2D45F9',type:'prospect'})}}}>Ajouter l’étape</button></div></div></section>}
function IntegrationSettings({state,iid}){const ghl=(state.integrations||[]).find(x=>x.institutId===iid&&x.provider==='ghl');return <div className="integration-grid">{[['GoHighLevel',ghl?.locationId?'Connecté':'Configuré par Presty','Réception automatique des formulaires et routage vers votre CRM.'],['Meta Ads','À connecter','Aperçu des campagnes, dépenses, leads et CPL.'],['Fiche d’établissement Google','À connecter','Connexion Google Business Profile pour centraliser les informations de votre établissement.'],['Google Ads','Plus tard','Connexion prévue dans une future version.']].map(([name,status,desc])=><section className="panel integration-tile" key={name}><div><span className="eyebrow">INTÉGRATION</span><h3>{name}</h3><p className="muted">{desc}</p></div><span className="soft-badge">{status}</span></section>)}</div>}

function PageHead({title,desc,children}){return <div className="page-head"><div><h1>{title}</h1><p>{desc}</p></div>{children&&<div className="page-actions">{children}</div>}</div>}
function Modal({title,close,children}){return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="modal"><div className="modal-head"><h3>{title}</h3><button className="close" onClick={close}>×</button></div>{children}</div></div>}
function Drawer({title,close,children}){return <div className="drawer-overlay" onMouseDown={e=>e.target===e.currentTarget&&close()}><aside className="drawer"><div className="modal-head"><h3>{title}</h3><button className="close" onClick={close}>×</button></div>{children}</aside></div>}
function Empty({text}){return <div className="empty-state">{text}</div>}
